mapper.select:
SELECT SP.ChnlCode, SP.StoreCode, SP.ProdCode, SP.LocType, SP.ProdSeq, SP.OrderQty, SP.Remark, SP.State, SP.RegistDate, SP.RegistId, SP.RegistName, SP.ChangeDate, SP.ChangeId, SP.ChangeName, PH.ProdName, PH.SalePrice, PH.SaleYn, PH.SupplyQty, PH.ImgUrl80, PH.BrandName, PC.CpnAmt AS ProdCpnAmt, PT.PointAmt FROM shopion.tStrStoreProd SP INNER JOIN shopion.tPrdProd PH ON SP.ProdCode = PH.ProdCode LEFT JOIN shopion.tStrProdCpnProd CPP ON SP.ChnlCode = CPP.ChnlCode AND SP.ProdCode = CPP.ProdCode LEFT JOIN shopion.tStrProdCpn PC ON CPP.CpnId = PC.CpnId LEFT JOIN shopion.tStrPointProd PP ON SP.ChnlCode = PP.ChnlCode AND SP.ProdCode = PP.ProdCode LEFT JOIN shopion.tStrPoint PT ON PP.PointId = PT.PointId
ORDER BY CASE WHEN PH.BrandName IN ('캐시캐시','캐시캐시키즈') THEN 0 ELSE 1 END, SP.ProdSeq
ORDER BY SP.ProdSeq
LIMIT #{topCnt}
LIMIT #{startNum}, #{countPerPage}

SELECT SP.ChnlCode, SP.StoreCode, SP.ProdCode, SP.LocType, SP.ProdSeq, SP.OrderQty, SP.Remark, SP.State, SP.RegistDate, SP.RegistId, SP.RegistName, SP.ChangeDate, SP.ChangeId, SP.ChangeName, PH.ProdName, PH.SalePrice, PH.SaleYn, PH.SupplyQty, PH.ImgUrl80 FROM shopion.tStrStoreProd SP INNER JOIN shopion.tPrdProd PH ON SP.ProdCode = PH.ProdCode
AND SP.ChnlCode = #{pChnlCode}
AND SP.StoreCode = #{pStoreCode}
AND SP.LocType IS NOT NULL AND SP.LocType != 0
ORDER BY SP.LocType, SP.ProdSeq

SELECT SP.ChnlCode, SP.StoreCode, SP.ProdCode, SP.LocType, SP.ProdSeq,
       SP.Remark, SP.State,
       SP.RegistDate, SP.RegistId, SP.RegistName, SP.ChangeDate, SP.ChangeId, SP.ChangeName,
       PH.ProdName, PH.SalePrice, PH.SaleYn, PH.ImgUrl80,
       IFNULL(OQ.OrderQty, 0) AS OrderQty
FROM shopion.tStrStoreProd SP
INNER JOIN shopion.tPrdProd PH ON SP.ProdCode = PH.ProdCode
LEFT JOIN (
    SELECT ProdCode, SUM(ProdQty) AS OrderQty
    FROM shopion.tOrdOrderProd


            AND RegistDate >= #{pOrderStartDate}


            AND RegistDate <= #{pOrderEndDate}


    GROUP BY ProdCode
) OQ ON SP.ProdCode = OQ.ProdCode


        AND SP.ChnlCode = #{pChnlCode}


        AND SP.StoreCode = #{pStoreCode}


ORDER BY OrderQty DESC

    LIMIT #{topCnt}

SELECT MIN(StoreCode)
FROM shopion.tStrStoreProd
WHERE ProdCode = #{pProdCode}

    AND ChnlCode = #{pChnlCode}

SELECT ChnlCode, StoreCode, ProdCode, LocType, ProdSeq, OrderQty,
       Remark, State, RegistDate, RegistId, RegistName, ChangeDate, ChangeId, ChangeName
FROM shopion.tStrStoreProd
WHERE ChnlCode = #{pChnlCode}
  AND StoreCode = #{pStoreCode}
  AND ProdCode = #{pProdCode}

mapper.insert:
INSERT INTO shopion.tStrStoreProd (
    ChnlCode, StoreCode, ProdCode, LocType, ProdSeq, OrderQty,
    Remark, State, RegistDate, RegistId, RegistName, ChangeDate, ChangeId, ChangeName
) VALUES (
    #{chnlCode}, #{storeCode}, #{prodCode}, #{locType}, #{prodSeq}, #{orderQty},
    #{remark}, #{state}, #{registDate}, #{registId}, #{registName}, #{changeDate}, #{changeId}, #{changeName}
)

mapper.update:
UPDATE shopion.tStrStoreProd
SET LocType = #{locType},
    ProdSeq = #{prodSeq},
    OrderQty = #{orderQty},
    Remark = #{remark},
    State = #{state},
    ChangeDate = #{changeDate},
    ChangeId = #{changeId},
    ChangeName = #{changeName}
WHERE ChnlCode = #{chnlCode}
  AND StoreCode = #{storeCode}
  AND ProdCode = #{prodCode}

